definition.raw:
\label{milnorsquare}
A \emph{Milnor square} of commutative rings is a diagram
\begin{equation}  \xymatrix{
S \ar[d] \ar[r]&  T \ar[d]  \\
S'  \ar[r] &  T'
} \label{milnsquare} \end{equation} 
such that the vertical arrows are surjective and such that the diagram is both
cartesian and cocartesian in the category of commutative rings. 
It follows in particular that 
if $I \subset S$, $J \subset T$
are the respective kernels of the vertical maps $S \to S'$, $T \to T'$, then $f|_I
: I \stackrel{\simeq}{\to} J$ establishes an isomorphism of the ideals $I$, $J$.

\begin{enumerate}
\item  
A functor $\mathrm{Ring}^{\mathrm{nu,h}}_R \to \mathrm{Ab}$ is \emph{projectively finitely generated} 
if it is $\mathcal{D}$-finitely generated for $\mathcal{D} = (\mathrm{Ring}^{\mathrm{nu,h}}_R)_{\Sigma}$.
\item
A functor $\mathrm{Ring}^{\mathrm{nu,h}}_R \to \mathrm{Sp}$ is \emph{projectively pseudocoherent} if it
is $\mathcal{D}$-pseudocoherent for $\mathcal{D} = (\mathrm{Ring}^{\mathrm{nu,h}}_R)_\Sigma$. 
\end{enumerate}

\label{Ffinite}
An $\mathbb{F}_p$-algebra $R$ is said to be \emph{$F$-finite} if the absolute Frobenius
map $R \to R$ is finite, in other words if $R$ is a finitely generated module over its subring of $p^\sub{th}$-powers.

theorem.raw:
\label{DGMthm}
Let $R \to R'$ be a map of rings which is a surjection with nilpotent
kernel.\footnote{Or, more generally, a map of connective $\mathbb{E}_1$-ring spectra such that $\pi_0R\rightarrow\pi_0R'$ is a surjection with  nilpotent kernel} Then the map $K^{\mathrm{inv}}(R) \to K^{\mathrm{inv}}(R')$ is an equivalence.

\label{gabberthm}
Let $(R, I)$ be a henselian pair. Suppose $n$ is invertible in $R$. Then the map
$K(R)/n \to K(R/I)/n$ is an equivalence of spectra.

\label{ourthm}
Let $(R, I)$ be a henselian pair. Then for any $n$, the map
$K^{\mathrm{inv}}(R)/n \to K^{\mathrm{inv}}(R/I)/n$ is an equivalence.

Let $R$ be a smooth $\mathbb{F}_p$-algebra. Then, for each $s\ge1$, we have an 
isomorphism of graded rings
\begin{equation} \label{HHKR1}  \mathrm{TR}^s_*(R; p) \simeq W_s \Omega^{\ast}_R \otimes_{\mathbb{Z}/p^s}
\mathbb{Z}/p^s [ \sigma_s], \quad |\sigma_s| = 2.  \end{equation}
The Restriction maps
are determined by the Restriction maps on the de Rham--Witt complex and send 
$\sigma_s \mapsto p  \sigma_{s-1}$. 
Therefore, we have an isomorphism
\begin{equation}  \label{HHKR2} \mathrm{TR}_*(R; p) \simeq W \Omega^{\ast}_R,  \end{equation}
and the $F$ map on $\mathrm{TR}(R; p)$ induces the $F$ map on $W \Omega_R^{\ast}$.

\label{etalekthm}
Let $R$ be a strictly henselian local ring of residue characteristic $p$. Then $K^{\mathrm{inv}}(R)/p =0$, i.e., the map $K(R) \to \mathrm{TC}(R)$ is a
$p$-adic equivalence.

\label{KTCasymptotic}
Let $R$ be a commutative ring and $p$ be a prime number. Suppose that $d
\geq 1$ and:  
\begin{enumerate}
\item  $R$ is henselian along $(p)$. 
\item The ring $R/p$ has finite Krull dimension.  
\item For any $x \in \mathrm{Spec} (R/p)$, the residue field $k(x)$ has the property that
$[k(x): k(x)^p] \leq p^d$. \end{enumerate}
The map $K(R)/p^r
\to \mathrm{TC}(R)/p^r$ is an equivalence in degrees $\geq d$ for any $r$.

