corollary.raw:
\label{TCring}
The functor $\mathrm{Alg}(\mathrm{Sp}_{\geq 0})\to\mathrm{Sp}$, $R \mapsto \mathrm{TC}(R)/p$ commutes with
sifted colimits.

\label{kanextcrit}
Let $\mathcal{E}$ be an $\infty$-category with sifted colimits, and let $F: \mathrm{Ring}^{\mathrm{nu,h}}_R \to \mathcal{E}$ be a functor. Then the following are equivalent: 
\begin{enumerate}
\item $F$ is left Kan extended from $(\mathrm{Ring}^{\mathrm{nu,h}}_R)_{\Sigma} \subset \mathrm{Ring}^{\mathrm{nu,h}}_R$. 
\item Whenever $I_\bullet$ is a simplicial object in $\mathrm{Ring}^{\mathrm{nu,h}}_R$ whose geometric
realization is equivalent to $I_{-1} \in \mathrm{Ring}^{\mathrm{nu,h}}_R$ (in particular, the homotopy type
of the underlying simplicial set of $I_\bullet$ is discrete), then the map 
$|F(I_\bullet)| \to F(I_{-1})$ is an equivalence.\footnote{Since the category
of nonunital henselian rings is the category of algebras over a monad on the
category of sets, there is always a canonical resolution of any object by free
objects; it would suffice to consider these resolutions.} 
Furthermore, $F$ commutes with filtered colimits. 
\end{enumerate}

\label{corollary_Milnor}
Let $R$ be an $F$-finite, regular, noetherian $\mathbb F_p$-algebra and $I\subseteq R$ an ideal such that $R/I$ is local. Then, for all $n,r\ge0$:
\begin{enumerate}
\item the canonical map $\{K_n^M(R/I^s)/p^r\}_s\to\{K_n(R/I^s;\mathbb Z/p^r)\}_s$ is surjective and has the same kernel as $\dlog[\cdot]:\{K_n^M(R/I^s)/p^r\}_s\to \{W_r\Omega^n_{R/I^s}\}_s$;
\item the pro abelian group $\{K_n(R/I^s)\}_s$ is $p$-torsion-free.
\end{enumerate}

\label{corollary_lifting}
Let $R$ be an $F$-finite, regular, noetherian, local  $\mathbb F_p$-algebra and $I\subseteq R$ an ideal. Then, for all $n,r\ge0$:
\begin{enumerate}
\item the sequences \[0\longrightarrow \{K_n(R,I^s;\mathbb Z/p^r\mathbb Z)\}_s\longrightarrow K_n(R;\mathbb Z/p^r\mathbb Z)\longrightarrow\{K_n(R/I^s;\mathbb Z/p^r\mathbb Z)\}_s\longrightarrow 0\] are short exact;
\item there exists $s\ge 1$ with the following property: if an element of
$K_n(R/I;\mathbb Z/p^r\mathbb Z)$ lifts to $K_n(R/I^s;\mathbb Z/p^r\mathbb Z)$, then it is
symbolic and hence lifts to $K_n(R)$. 
\end{enumerate}

